def gen(rng):
    def fmt(a, k):
        return f'{len(a)} {k}\n' + ' '.join(map(str, a))

    tests = [fmt([7], 1), fmt([3, 3, 3, 3], 2), fmt([5, 1, 4, 2, 3], 1), fmt([5, 1, 4, 2, 3], 5),
             fmt([-1, -1, 0, -2], 3), fmt([2, 1], 2), fmt([10 ** 9, -10 ** 9, 0], 2),
             fmt([2, 2, 5], 3), fmt([4, 4, 1, 1, 9], 4)]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for hi in (3, 50, 10 ** 9):
            if hi == 10 ** 9 and n > 20:
                continue
            a = [rng.randint(-hi, hi) for _ in range(n)]
            tests.append(fmt(a, rng.randint(1, n)))
    N = 100000
    lim = 10 ** 9
    tests.append(fmt([rng.randint(-lim, lim) for _ in range(N)], N // 2))
    tests.append(fmt(sorted(rng.randint(-lim, lim) for _ in range(N)), N - 5))
    tests.append(fmt(sorted((rng.randint(-lim, lim) for _ in range(N)), reverse=True), 3))
    tests.append(fmt([rng.randint(1, 10) for _ in range(N)], rng.randint(1, N)))
    return tests

